frappe.web_form.on('one_fm_applicant_password', (field, value) => {
    if(frappe.web_form.get_value('one_fm_applicant_password')){
      var success_message = __("Your Application is Submitted Successfully.\n\
        Please Log in With Your Email ID and Password {0} to Complete the Application.", [frappe.web_form.get_value('one_fm_applicant_password')])
      frappe.web_form.success_message = success_message;
    }
});

frappe.web_form.on('one_fm_email_id', (field, value) => {
  if(frappe.web_form.get_value('one_fm_email_id')){
    frappe.call({
      method: 'one_fm.utils.check_if_user_exist_as_desk_user',
      args: {'user': frappe.web_form.get_value('one_fm_email_id')},
      callback: function(r) {
        if(r && r.message){
          if(r.message == 'Website User'){
            frappe.web_form.set_df_property('one_fm_applicant_password', 'hidden', 1);
            frappe.web_form.set_value('one_fm_applicant_password', '');
          }
          else{
            frappe.web_form.set_value('one_fm_email_id', '');
            frappe.throw(__("This Email Id is already registerd as a Desk User. You cannot Apply"))
          }
        }
        else{
          frappe.web_form.set_df_property('one_fm_applicant_password', 'hidden', 0);
        }
      }
    });
  }
  else{
    frappe.web_form.set_df_property('one_fm_applicant_password', 'hidden', 0);
  }
});

frappe.web_form.on('one_fm_first_name', (field, value) => {
